import { beforeEach, describe, expect, it, vi } from "vitest";
import { act, renderHook, waitFor } from "@testing-library/react";

vi.mock("@/app/(roles)/mobo/trade-reconciliation/actions", () => ({
  getFlow: vi.fn(),
}));

import { getFlow } from "@/app/(roles)/mobo/trade-reconciliation/actions";
import { useReconciliationFlow } from "@/hooks/api/useReconciliationFlow";
import type { ReconciliationFlowViewDTO } from "@/lib/mobo/flow-types";

function ok<T>(data: T) {
  return { success: true as const, data };
}
function fail(error: string, code = "NETWORK_ERROR") {
  return { success: false as const, error, code };
}

function dto(overrides: Partial<ReconciliationFlowViewDTO> = {}): ReconciliationFlowViewDTO {
  return {
    settleDay: "03 Jun 2026",
    orders: [], allocs: [], ports: [],
    algoTotal: "$0", ibTotal: "$0", crmTotal: "$0",
    counts: { algIbBrk: 0, ibCrmBrk: 0, algCrmBrk: 0, totalBrk: 0 },
    ...overrides,
  };
}

// Each test uses its own sessionId so the hook's module-scoped cache
// (keyed by sessionId ?? "__latest__") never bleeds state between tests.
describe("FE-3 useReconciliationFlow", () => {
  beforeEach(() => vi.clearAllMocks());

  it("fetches and populates data on mount", async () => {
    vi.mocked(getFlow).mockResolvedValue(ok(dto({ settleDay: "04 Jun 2026" })));
    const { result } = renderHook(() => useReconciliationFlow("sess-1"));
    expect(result.current.loading).toBe(true);
    await waitFor(() => expect(result.current.loading).toBe(false));
    expect(result.current.data?.settleDay).toBe("04 Jun 2026");
    expect(getFlow).toHaveBeenCalledWith("sess-1");
  });

  it("a failed fetch sets error and leaves data null", async () => {
    vi.mocked(getFlow).mockResolvedValue(fail("boom"));
    const { result } = renderHook(() => useReconciliationFlow("sess-2"));
    await waitFor(() => expect(result.current.loading).toBe(false));
    expect(result.current.error).toBe("boom");
    expect(result.current.data).toBeNull();
  });

  it("a second hook instance for the same sessionId is seeded from the module cache immediately", async () => {
    vi.mocked(getFlow).mockResolvedValue(ok(dto({ settleDay: "05 Jun 2026" })));
    const { result: first } = renderHook(() => useReconciliationFlow("sess-3"));
    await waitFor(() => expect(first.current.loading).toBe(false));

    const { result: second } = renderHook(() => useReconciliationFlow("sess-3"));
    expect(second.current.data).toEqual(first.current.data);
  });

  it("refetch() re-triggers a fetch and overwrites the cache on success", async () => {
    vi.mocked(getFlow).mockResolvedValue(ok(dto({ settleDay: "06 Jun 2026" })));
    const { result } = renderHook(() => useReconciliationFlow("sess-4"));
    await waitFor(() => expect(result.current.loading).toBe(false));

    vi.mocked(getFlow).mockResolvedValue(ok(dto({ settleDay: "07 Jun 2026" })));
    await act(async () => result.current.refetch());
    await waitFor(() => expect(result.current.data?.settleDay).toBe("07 Jun 2026"));
    expect(getFlow).toHaveBeenCalledTimes(2);
  });

  it("calling refetch() while a fetch is already in flight is a no-op (the inFlight guard)", async () => {
    let resolveFirst!: (v: ReturnType<typeof ok<ReconciliationFlowViewDTO>>) => void;
    vi.mocked(getFlow).mockReturnValueOnce(
      new Promise((resolve) => { resolveFirst = resolve; }),
    );
    const { result } = renderHook(() => useReconciliationFlow("sess-5"));
    expect(result.current.loading).toBe(true);

    act(() => { result.current.refetch(); }); // fires while the first fetch is still in flight
    expect(getFlow).toHaveBeenCalledTimes(1); // second call was swallowed by the inFlight guard

    await act(async () => resolveFirst(ok(dto())));
    await waitFor(() => expect(result.current.loading).toBe(false));
  });
});
